const SUPPORTED=LANGUAGES.filter(x=>x[0]!=="auto").map(x=>x[0]);
const LANGUAGE_NAMES=Object.fromEntries(LANGUAGES);

function browserLanguage(){
  const candidates=(navigator.languages&&navigator.languages.length?navigator.languages:[navigator.language||"en"]);
  for(const loc of candidates){
    const base=(loc||"").toLowerCase().split("-")[0];
    if(SUPPORTED.includes(base)) return base;
  }
  return "en";
}
function storedLanguage(){
  const saved=localStorage.getItem("actinsynch.language");
  return saved && (saved==="auto" || SUPPORTED.includes(saved)) ? saved : "auto";
}
function activeLanguage(){
  const saved=storedLanguage();
  return saved==="auto" ? browserLanguage() : saved;
}
function translateValue(lang,key,fallback=""){
  const pack=I18N[lang]||I18N.en;
  return pack[key]!==undefined ? pack[key] : (I18N.en[key]!==undefined ? I18N.en[key] : fallback);
}
function applyLanguage(lang){
  document.documentElement.lang=lang;
  document.querySelectorAll("[data-i18n]").forEach(el=>{
    const key=el.dataset.i18n;
    const value=translateValue(lang,key,el.textContent);
    if(el.hasAttribute("data-i18n-html")) el.innerHTML=value; else el.textContent=value;
  });
  const trigger=document.querySelector(".lang-trigger");
  if(trigger){
    const mode=storedLanguage();
    trigger.textContent = mode==="auto" ? `Auto · ${LANGUAGE_NAMES[lang]||"English"}` : (LANGUAGE_NAMES[lang]||"English");
  }
  document.querySelectorAll(".lang-option").forEach(b=>b.classList.toggle("active",b.dataset.lang===storedLanguage()));
}
function setLanguagePreference(code){
  localStorage.setItem("actinsynch.language",code);
  applyLanguage(code==="auto" ? browserLanguage() : code);
}
function buildLanguagePicker(){
  const root=document.querySelector(".lang");
  if(!root) return;
  const trigger=root.querySelector(".lang-trigger");
  const panel=root.querySelector(".lang-panel");
  panel.innerHTML="";
  LANGUAGES.forEach(([code,name])=>{
    const b=document.createElement("button");
    b.type="button"; b.className="lang-option"; b.dataset.lang=code; b.textContent=name;
    b.addEventListener("click",()=>{ setLanguagePreference(code); panel.classList.remove("open"); });
    panel.appendChild(b);
  });
  trigger.addEventListener("click",e=>{e.stopPropagation();panel.classList.toggle("open")});
  document.addEventListener("click",()=>panel.classList.remove("open"));
}
document.addEventListener("DOMContentLoaded",()=>{
  buildLanguagePicker();
  applyLanguage(activeLanguage());
  const toggle=document.querySelector(".mobile-toggle"), nav=document.querySelector(".nav");
  if(toggle&&nav) toggle.addEventListener("click",()=>nav.classList.toggle("open"));
});
